"""Embedded visual asset for the Kulechek mascot.

Source: Maria's approved tricolor dog in a fluffy pink heart hood.
Stored as a compact JPEG so the same mascot can be served by the WebApp
and sent by the Telegram bot without depending on an external CDN.
"""

import base64
import io

_MASCOT_JPEG_BASE64 = """

""".strip()


def image_bytes():
    return base64.b64decode(_MASCOT_JPEG_BASE64)


def image_file():
    data = io.BytesIO(image_bytes())
    data.name = "kulechek.jpg"
    return data
